return function(build,ui,frame,filterTool)
	filterTool("Campaign and base-family");frame("filter-campaign-empty");ui:click("starters");frame("filter-campaign-starters");ui:click("close");local compact=main.popups[1].controls.page~=nil;if compact then ui:click("pageWeapons") end;ui:click("weapons1");if compact then ui:click("pageArmour") end;ui:click("defences3");if compact then ui:click("pageRecipes") end;ui:click("recipe1");ui:click("recipe5");ui:click("recipe6");ui:click("recipe7");ui:click("recipe8");ui:click("recipe9");ui:click("recipe10");frame("filter-campaign-quality-pickups");ui:click("rareSetSlots");ui:click("slot2");ui:click("slot3");frame("filter-rare-set-slots");ui:click("keep");if compact then ui:click("pageSetup") end;ui:text("minAreaLevel","80");ui:text("maxAreaLevel","60");ui:click("keep");frame("filter-campaign-invalid");ui:click("close");ui:text("minAreaLevel","10");ui:text("minDropLevel","10");ui:text("minLinks","2");ui:text("upgradeWindow","20");frame("filter-campaign-selected");ui:click("keep")
	local campaignDraft=build.planningWorkspace.cache.filters.layout.snapshot().data.profiles[1].campaign
	assert(campaignDraft.weapons[1]=="Bow" and #campaignDraft.defences==1 and #campaignDraft.recipes==7 and campaignDraft.recipes[2]=="Unidentified rare set pieces" and campaignDraft.recipes[3]=="Low-level unidentified rare set pieces" and campaignDraft.recipes[4]=="Vaal skill gems" and campaignDraft.recipes[5]=="Quality flasks and tinctures" and campaignDraft.recipes[6]=="Quality weapons" and campaignDraft.recipes[7]=="Quality armour","Campaign pickup choices were not kept in the draft")
	assert(#campaignDraft.rareSetSlots==1 and campaignDraft.rareSetSlots[1]=="Jewellery","Rare-set slot groups were not kept in the draft")
	assert(campaignDraft.minAreaLevel==10 and campaignDraft.maxAreaLevel==60 and campaignDraft.minDropLevel==10 and campaignDraft.minLinks==2 and campaignDraft.upgradeWindow==20,"Campaign numeric edits were ignored")
end
